import { test, expect } from '@playwright/test';

test.describe('Restore Archived Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
    await page.getByRole('button', { name: 'Archived Records' }).click();
  });

  test('should display archived records', async ({ page }) => {
    const archivedRecord = await page.getByText('Archived Record 1');
    await expect(archivedRecord).toBeVisible();
  });

  test('should restore an archived record', async ({ page }) => {
    await page.getByText('Archived Record 1').click();
    await page.getByRole('button', { name: 'Restore' }).click();
    await page.getByRole('alert').waitFor();
    const successMessage = await page.getByText('Record restored successfully');
    await expect(successMessage).toBeVisible();

    await page.goto('/records');
    const restoredRecord = await page.getByText('Archived Record 1');
    await expect(restoredRecord).toBeVisible();
  });
});
